 43 | export async function request<T>(endpoint: string, options: RequestOptions = {}): Promise<T> {
 44 |   const { params, headers, ...customConfig } = options;
 45 | 
 46 |   let url = endpoint.startsWith('http')
 47 |     ? endpoint
 48 |     : `${API_BASE_URL}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`;
 49 | 
 50 |   if (params) {
 51 |     const searchParams = new URLSearchParams();
 52 |     Object.entries(params).forEach(([key, value]) => {
 53 |       if (value !== undefined && value !== null) {
 54 |         searchParams.append(key, String(value));
 55 |       }
 56 |     });
 57 |     const queryString = searchParams.toString();
 58 |     if (queryString) {
 59 |       url += (url.includes('?') ? '&' : '?') + queryString;
 60 |     }
 61 |   }
 62 | 
 63 |   const defaultHeaders: Record<string, string> = {
 64 |     'Content-Type': 'application/json',
 65 |   };
 66 | 
 67 |   // Retrieve token dynamically from Clerk Auth bridge or fallback
 68 |   let token=<redacted> | null = null;
 69 | 
 70 |   if (globalAuthTokenGetter) {
 71 |     try {
 72 |       token=<redacted> globalAuthTokenGetter();
 73 |     } catch (err) {
 74 |       console.warn('[apiClient] Error retrieving session token from auth getter:', err);
 75 |     }
 76 |   }
 77 | 
 78 |   if (!token && typeof window !== 'undefined') {
 79 |     const clerk = (window as unknown as { Clerk?: { session?: { getToken: () => Promise<string | null> } } }).Clerk;
 80 |     if (clerk?.session) {
 81 |       try {
 82 |         token=<redacted> clerk.session.getToken();
 83 |       } catch {
 84 |         // Continue to fallback
 85 |       }
 86 |     }
 87 |     if (!token) {
 88 |       token=<redacted>'zentrix_auth_token');
 89 |     }
 90 |   }
 91 | 
 92 |   if (token) {
 93 |     defaultHeaders['Authorization'] = `Bearer ${token}`;
 94 |   }
 95 | 
 96 |   const config: RequestInit = {
 97 |     method: 'GET',
 98 |     credentials: 'include',
 99 |     headers: {
100 |       ...defaultHeaders,
101 |       ...headers,
102 |     },
103 |     ...customConfig,
104 |   };
105 | 
106 |   try {
107 |     const response = await fetch(url, config);
108 | 
109 |     if (!response.ok) {
110 |       let errorData: ApiErrorResponse | null = null;
111 |       try {
112 |         errorData = await response.json();
113 |       } catch {
114 |         // Not JSON
115 |       }
116 | 
117 |       let message = `API error ${response.status}: ${response.statusText}`;
118 |       if (errorData?.detail) {
119 |         if (typeof errorData.detail === 'string') {
120 |           message = errorData.detail;
121 |         } else if (Array.isArray(errorData.detail)) {
122 |           message = errorData.detail
123 |             .map((e: unknown) => {
124 |               if (typeof e === 'object' && e !== null) {
125 |                 const item = e as Record<string, unknown>;
126 |                 return String(item.msg || item.message || JSON.stringify(e));
127 |               }
128 |               return String(e);
129 |             })
130 |             .join(', ');
131 |         }
132 |       } else if (errorData?.message) {
133 |         message = errorData.message;
134 |       }
135 | 
136 |       throw new ApiError(message, response.status, errorData);
137 |     }
138 | 
139 |     if (response.status === 204) {
140 |       return {} as T;
141 |     }
142 | 
143 |     return (await response.json()) as T;
144 |   } catch (err: unknown) {
145 |     if (err instanceof ApiError) {
146 |       throw err;
147 |     }
148 |     const message = err instanceof Error ? err.message : 'Network error';
149 |     throw new ApiError(message, 0, err);
150 |   }
151 | }
